    while (i + count < n && s[i] == s[i + count] && count < 255)
      count++;
    if (j + 2 > m)
      return -1;
    r[j++] = count;
    r[j++] = s[i];
    i += count;
  }
  while (i < n) {
    size_t count = 1;
